arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *sername*) echo "x-access-token" ;;
  *assword*) printf '%s\n' "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/askpass.sh && cd /tmp/conv-rachel && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git push origin HEAD:refs/heads/friend/rachel 2>&1 | tail -5 && git log --oneline -4
